import{at as e,it as t,n,vt as r}from"./chunks/framework.BVWCHfG0.js";var i=JSON.parse(`{"title":"Managing pull requests","description":"","frontmatter":{},"headers":[],"relativePath":"maintainer-guide/pull-requests.md","filePath":"docs/maintainer-guide/pull-requests.md","lastUpdated":1791105871000}`),a={name:`maintainer-guide/pull-requests.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e('<h1 id="managing-pull-requests" tabindex="-1">Managing pull requests <a class="header-anchor" href="#managing-pull-requests" aria-label="Permalink to “Managing pull requests”">​</a></h1><p>You should:</p><ul><li>use <a href="https://docs.github.com/en/pull-requests/collaborating-with-pull-requests/reviewing-changes-in-pull-requests/about-pull-request-reviews" target="_blank" rel="noreferrer">GitHub reviews</a></li><li>review against\xA0the\xA0<a href="/developer-guide/rules">Developer guide criteria</a></li><li>resolve conflicts by\xA0<a href="https://www.atlassian.com/git/tutorials/rewriting-history/git-rebase" target="_blank" rel="noreferrer">rebasing</a></li></ul><p>A\xA0pull request carries no labels or\xA0milestones: those belong to\xA0the\xA0issue it closes.</p><h2 id="merging" tabindex="-1">Merging <a class="header-anchor" href="#merging" aria-label="Permalink to “Merging”">​</a></h2><p>When\xA0merging a\xA0PR, you should:</p><ol><li><p>Use your judgment for\xA0the\xA0number of\xA0approvals needed:</p><ul><li>one approval is usually fine for\xA0simple fixes,</li><li>two\xA0approvals are often useful for\xA0bigger changes.</li></ul></li><li><p>If\xA0the\xA0change is significant to\xA0users, add a\xA0description of\xA0the\xA0change to\xA0the\xA0changelog:</p><ul><li><p>in\xA0the\xA0Unreleased section, select (or\xA0add if\xA0not\xA0already there) one of\xA0three\xA0possible sub-sections:</p><ul><li><strong>Changed</strong>\xA0— for\xA0a\xA0breaking change that\xA0requires users to\xA0do something when\xA0updating, and\xA0for\xA0a\xA0fixed false negative, which\xA0users meet as\xA0new warnings;</li><li><strong>Added</strong>\xA0— for\xA0a\xA0new feature (rule, option, etc.) that\xA0does not\xA0require users to\xA0do anything when\xA0updating;</li><li><strong>Fixed</strong>\xA0— to\xA0fix a\xA0bug in\xA0an\xA0existing feature.</li></ul></li><li><p>If\xA0possible, add to\xA0the\xA0change description an\xA0explanation of\xA0what the\xA0user must (in\xA0case of\xA0breaking changes) or\xA0can do now.</p><p>For\xA0example:</p><div class="language-markdown"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### Changed</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> The\xA0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`named-grid-areas-alignment`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rule now applies to\xA0the\xA0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`grid-template`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> and\xA0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`grid`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> properties as\xA0well. If\xA0you used this rule for\xA0the\xA0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`grid-template-areas`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> property, you may have new linting errors\xA0— you must fix your code (e.g. by\xA0running linting with\xA0the\xA0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`--fix`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> flag).</span></span></code></pre></div></li></ul></li><li><p><a href="https://docs.github.com/en/pull-requests/collaborating-with-pull-requests/incorporating-changes-from-a-pull-request/about-pull-request-merges#squash-and-merge-your-commits" target="_blank" rel="noreferrer">&quot;Squash and\xA0merge&quot;</a> the\xA0commits. GitHub appends the\xA0pull request&#39;s number to\xA0the\xA0subject itself; check that\xA0the\xA0subject is one imperative sentence, e.g. “Write the\xA0newline <code>value-list-comma-newline-before</code> asks for\xA0(#742)”. GitHub also fills the\xA0body with\xA0the\xA0pull request&#39;s description, which\xA0is written for\xA0the\xA0discussion: replace it with\xA0a\xA0short account of\xA0why the\xA0change is needed.</p></li></ol>',7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};